begin;
create extension if not exists pgtap with schema extensions;
select plan(31);
insert into public.entries(id,owner_id,title,entry_type) values('96000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Pottery milestone','goal');
insert into public.goals(entry_id,owner_id) values('96000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001');
insert into public.collections(id,owner_id,name) values('96000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','Bucket List');
insert into public.entry_collections(entry_id,owner_id,collection_id) values('96000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','96000000-0000-4000-8000-000000000002');
insert into public.tags(id,owner_id,name) values('96000000-0000-4000-8000-000000000003','10000000-0000-0000-0000-000000000001','Organization test tag');
insert into public.entry_tags(entry_id,owner_id,tag_id) values('96000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','96000000-0000-4000-8000-000000000003');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is((select entry_count from public.organization_workspace('collection','bucket')),1::bigint,'Collection linked count and search');
select ok(public.save_organization('collection',' Empty collection ',-100) is not null,'Create empty Collection');
select is((select name from public.organization_workspace('collection','',1,0)),'Empty collection','Ordering and pagination');
select is(public.save_organization('collection','Someday adventures',-50,'96000000-0000-4000-8000-000000000002',1),'96000000-0000-4000-8000-000000000002'::uuid,'Rename Collection preserves ID');
select is((select system_key from public.collections where id='96000000-0000-4000-8000-000000000002'),'bucket_list','Bucket List role remains stable');
select is((select revision from public.entries where id='96000000-0000-4000-8000-000000000001'),2,'Rename invalidates stale Entry reviews');
select is((select snapshot->'collections'->0->>'name' from public.entry_versions where entry_id='96000000-0000-4000-8000-000000000001' and version=1),'Bucket List','History captures pre-rename metadata');
select is((select is_bucket_list from public.goals_workspace() where entry_id='96000000-0000-4000-8000-000000000001'),true,'Goals UI receives stable role');
select is(public.save_organization('collection','Stale',0,'96000000-0000-4000-8000-000000000002',1),null::uuid,'Stale Collection save rejected');
select throws_ok($$select public.save_organization('collection','SOMEDAY ADVENTURES',0)$$,'23505',null,'Case-insensitive duplicate rejected');
select ok(public.save_organization('tag',' 新标签 ',0) is not null,'Create bilingual tag');
select is(public.save_organization('tag','Pottery',0,'96000000-0000-4000-8000-000000000003',1),'96000000-0000-4000-8000-000000000003'::uuid,'Rename tag preserves ID');
select is((select entry_count from public.organization_workspace('tag','pottery')),1::bigint,'Tag links preserved');
select is((select revision from public.entries where id='96000000-0000-4000-8000-000000000001'),3,'Tag rename invalidates stale Entry reviews');
select is(public.trash_collection('96000000-0000-4000-8000-000000000002',2),'96000000-0000-4000-8000-000000000002'::uuid,'Trash Collection');
select is((select count(*) from public.organization_workspace('collection','Someday')),0::bigint,'Trashed Collection hidden from management');
select is((select count(*) from public.trash_workspace() where item_kind='collection' and item_id='96000000-0000-4000-8000-000000000002'),1::bigint,'Collection appears in unified Trash');
select is((select deleted_at from public.entries where id='96000000-0000-4000-8000-000000000001'),null::timestamptz,'Entries never move to Trash with a Collection');
select is((select count(*) from public.entry_collections where collection_id='96000000-0000-4000-8000-000000000002'),1::bigint,'Trash preserves grouping for recovery');
select is((select count(*) from public.restore_trash_item('collection','96000000-0000-4000-8000-000000000002',3,(select archived_at from public.collections where id='96000000-0000-4000-8000-000000000002'))),1::bigint,'Restore Collection');
select is((select count(*) from public.mark_goal_achieved_with_first_time('96000000-0000-4000-8000-000000000001',5,'2026-09-12T12:00:00Z','day',null,'UTC')),1::bigint,'Renamed Bucket List still creates First Time');
select is(public.trash_collection('96000000-0000-4000-8000-000000000002',4),'96000000-0000-4000-8000-000000000002'::uuid,'Trash again');
select is((select count(*) from public.delete_trash_item_forever('collection','96000000-0000-4000-8000-000000000002',5,(select archived_at from public.collections where id='96000000-0000-4000-8000-000000000002'))),1::bigint,'Permanent grouping deletion');
select is((select count(*) from public.entries where id='96000000-0000-4000-8000-000000000001'),1::bigint,'Permanent Collection deletion still preserves Entry');
select throws_ok($$select public.save_organization('tag',' ',0)$$,'22023','invalid_organization_details','Empty name refused');
select throws_ok($$select public.save_organization('tag','x',1)$$,'22023','invalid_organization_details','Tags have no numeric order');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000099',true);
select is((select count(*) from public.organization_workspace('tag','Pottery')),0::bigint,'Other owner cannot read');
select is(public.save_organization('tag','Foreign',0,'96000000-0000-4000-8000-000000000003',2),null::uuid,'Other owner cannot edit');
reset role;
select ok(not has_function_privilege('anon','public.organization_workspace(text,text,integer,integer)','execute'),'Anonymous listing denied');
select ok(not has_function_privilege('anon','public.save_organization(text,text,integer,uuid,integer)','execute'),'Anonymous save denied');
select ok(not has_function_privilege('anon','public.trash_collection(uuid,integer)','execute'),'Anonymous Trash denied');
select * from finish();
rollback;
